return {
    -- BiVillageHead [8537]
    ["STR_ID_BiVillageHead[8537][Text1]"] = "Here, our way is simple and people are hardworking. But since the Bandits L97 came, peace is no longer with us. Monsters from other islands continuously",
    ["STR_ID_BiVillageHead[8537][Text2]"] = "Really? Those bandits are still enjoying beer and women? Good. I`ll make this disorderly mob collapse at the first blow!",
    ["STR_ID_BiVillageHead[8537][Text3]"] = "@STR_COMMON[14]",
    ["STR_ID_BiVillageHead[8537][Text4]"] = "Finally, we are rid of those Banditti! My hero, please wait! We have prepared a feast to thank you. Would you mind staying here and celebrating with us?",
    ["STR_ID_BiVillageHead[8537][Text5]"] = "It seems you haven`t killed 30 Banditti, have you? Make haste, please! I hope you can restore peace to our village.",
    ["STR_ID_BiVillageHead[8537][Text6]"] = "Oh, no! Someone told me 30 Banditti from the west and the northwest gathered outside the Fishing Village, again. It`s really annoying. Could you please go kill them?",
    ["STR_ID_BiVillageHead[8537][Text7]"] = "You`ve killed 30 Bandits L98? Great! It`s the SECOND time you saved our village! I can never thank you enough.",
    ["STR_ID_BiVillageHead[8537][Text8]"] = "It couldn`t be true. I`m sure those Bandits L98 are still watching our village, nearby. Please go check again, okay?",
    ["STR_ID_BiVillageHead[8537][Text9]"] = "It`s so good to see you! Those Bandits L97 haven`t give up their evil designs, and summoned lots of Bandits L98 from the desert. I can`t wait for them to rush",
    ["STR_ID_BiVillageHead[8537][Text10]"] = "What? You didn`t find Alvis? It`s really worrying. According to his route, Alvis should be on the Central Island. Could you go there and check again?",
    ["STR_ID_BiVillageHead[8537][Text11]"] = "Um... It has been more than 15 days since Alvis went to deliver the food supply to General Armand on the Central Island, and I received no reply back. It shouldn`t be more",
    ["STR_ID_BiVillageHead[8537][Text12]"] = "@STR_COMMON[14]",
    ["STR_ID_BiVillageHead[8537][Text13]"] = "Great job! I really don`t know how to thank you. You saved the whole village!",
    ["STR_ID_BiVillageHead[8537][Text14]"] = "Have you killed 50 Bandits L97? It seems the answer is no... Look, if you just kill a few of them, you will find that you`re only provoking them.",
    ["STR_ID_BiVillageHead[8537][Text15]"] = "You? I believe you are an able body, but there are many bandits, and all our young men have been drafted into the army. Are you sure you can deal with those brutes alone?",
    ["STR_ID_BiVillageHead[8537][Text16]"] = "It`s very kind of you! So, can you go kill 50 Bandits L97 on the Central Island, now? I suppose that is the best way to scare the other bandits away.",
    ["STR_ID_BiVillageHead[8537][Option1]"] = "Hey!~You~have~me,~now!",
    ["STR_ID_BiVillageHead[8537][Option2]"] = "~Food~Delivery~!",
    ["STR_ID_BiVillageHead[8537][Option3]"] = "Hunting~Bandits~L98.",
    ["STR_ID_BiVillageHead[8537][Option4]"] = "Hidden~Banditti.",
    ["STR_ID_BiVillageHead[8537][Option5]"] = "Return~Favors.",
    ["STR_ID_BiVillageHead[8537][Option6]"] = "It`s~terrible...",
